// Reads the connector manifest (vibe.manifest.json at the project root) out of a project's base64 zip bundle, so the backend can
// register it with the platform proxy. The bundle is generated by the worker, but it is still treated as untrusted input here:
// sizes are capped, nothing is extracted to disk and every failure is reported as "unreadable" instead of thrown.
// The proxy validates the manifest again when it is registered; this only locates and parses it.
import zlib from 'node:zlib';

export const MANIFEST_FILE = 'vibe.manifest.json';
const MAX_MANIFEST_BYTES = 8192;
const MAX_ENTRIES = 5000;

/** @returns {{status:'found', manifest:object} | {status:'none'} | {status:'unreadable'}} */
export function manifestFromBundle(bundleBase64) {
    try {
        if (typeof bundleBase64 !== 'string' || !bundleBase64) return { status: 'unreadable' };
        const zip = Buffer.from(bundleBase64, 'base64');
        if (zip.length < 22) return { status: 'unreadable' };
        let eocd = -1;
        for (let i = zip.length - 22; i >= Math.max(0, zip.length - 22 - 65535); i--) if (zip.readUInt32LE(i) === 0x06054b50) { eocd = i; break; }
        if (eocd < 0) return { status: 'unreadable' };
        const total = zip.readUInt16LE(eocd + 10);
        let off = zip.readUInt32LE(eocd + 16);
        if (total > MAX_ENTRIES) return { status: 'unreadable' };
        for (let n = 0; n < total; n++) {
            if (off + 46 > zip.length || zip.readUInt32LE(off) !== 0x02014b50) return { status: 'unreadable' };
            const method = zip.readUInt16LE(off + 10);
            const compSize = zip.readUInt32LE(off + 20);
            const size = zip.readUInt32LE(off + 24);
            const nameLen = zip.readUInt16LE(off + 28), extraLen = zip.readUInt16LE(off + 30), commentLen = zip.readUInt16LE(off + 32);
            const localOff = zip.readUInt32LE(off + 42);
            const name = zip.subarray(off + 46, off + 46 + nameLen).toString('utf8');
            off += 46 + nameLen + extraLen + commentLen;
            if (name !== MANIFEST_FILE) continue;
            if (size > MAX_MANIFEST_BYTES || compSize > MAX_MANIFEST_BYTES * 2) return { status: 'unreadable' };
            if (localOff + 30 > zip.length || zip.readUInt32LE(localOff) !== 0x04034b50) return { status: 'unreadable' };
            const start = localOff + 30 + zip.readUInt16LE(localOff + 26) + zip.readUInt16LE(localOff + 28);
            if (start + compSize > zip.length) return { status: 'unreadable' };
            const data = zip.subarray(start, start + compSize);
            let text;
            if (method === 0) text = data;
            else if (method === 8) text = zlib.inflateRawSync(data, { maxOutputLength: MAX_MANIFEST_BYTES + 1 });
            else return { status: 'unreadable' };
            if (text.length > MAX_MANIFEST_BYTES) return { status: 'unreadable' };
            const parsed = JSON.parse(text.toString('utf8'));
            if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed) || !parsed.connectors || typeof parsed.connectors !== 'object' || Array.isArray(parsed.connectors)) return { status: 'unreadable' };
            return Object.keys(parsed.connectors).length ? { status: 'found', manifest: parsed } : { status: 'none' };
        }
        return { status: 'none' };
    } catch {
        return { status: 'unreadable' };
    }
}
